<script>
 import { round } from '$lib/utils/helper'; import { getTeamFromTeamManagers } from '$lib/utils/helperFunctions/universalFunctions'; import { matchupInjurySentence } from './injuryStoryUtils.js'; import { favoriteTeamStory } from './favoriteTeamStoryUtils.js';
 export let matchupArray=[];export let players={};export let displayWeek;export let year;export let leagueTeamManagers;
 const n=v=>Number(round(Number(v)||0)),sum=a=>(a||[]).reduce((t,v)=>t+(Number(v)||0),0);const team=id=>{try{return getTeamFromTeamManagers(leagueTeamManagers,Number(id),year)||{name:`Team ${id}`}}catch(e){return{name:`Team ${id}`}}};const proj=e=>(e?.starters||[]).reduce((t,id)=>t+(Number(players?.[id]?.wi?.[displayWeek]?.p)||0),0);
 const build=()=>{const teams=[],games=[],loyaltyStories=[];for(const m of matchupArray||[]){if(!m?.[0]||!m?.[1])continue;const a=m[0],b=m[1],ap=n(sum(a.points)),bp=n(sum(b.points)),at=team(a.roster_id),bt=team(b.roster_id),injuryText=matchupInjurySentence(a,b,players,displayWeek,at.name,bt.name,'postgame'),loyalty=favoriteTeamStory(a,b,players,displayWeek,'postgame'),ar={id:a.roster_id,name:at.name,score:ap,projection:n(proj(a)),won:ap>bp,opp:bt.name,oppScore:bp},br={id:b.roster_id,name:bt.name,score:bp,projection:n(proj(b)),won:bp>ap,opp:at.name,oppScore:ap};teams.push(ar,br);games.push({a:ar,b:br,margin:n(Math.abs(ap-bp)),injuryText});if(loyalty)loyaltyStories.push(loyalty)}if(!teams.length)return{awards:[],verdict:''};const sorted=[...teams].sort((a,b)=>b.score-a.score);for(const t of teams)t.allPlayWins=teams.filter(o=>o.id!==t.id&&t.score>o.score).length;const wins=teams.filter(t=>t.won),losses=teams.filter(t=>!t.won),awards=[];for(const loyalty of loyaltyStories.slice(0,2))awards.push({label:loyalty.label,text:loyalty.text});const beatdown=[...games].sort((a,b)=>b.margin-a.margin)[0];if(beatdown&&beatdown.margin>=20){const w=beatdown.a.won?beatdown.a:beatdown.b,l=beatdown.a.won?beatdown.b:beatdown.a;awards.push({label:'💥 Beatdown of the Week',text:`${w.name} absolutely buried ${l.name} by ${beatdown.margin} points. This was not a close call — it was the biggest demolition of Week ${displayWeek}, and ${l.name} will be trying to forget it ever happened.${beatdown.injuryText}`})}const heart=[...games].filter(g=>g.margin<=7).sort((a,b)=>a.margin-b.margin)[0];if(heart){const l=heart.a.won?heart.b:heart.a;awards.push({label:'💔 Heartbreaker',text:`${l.name} came up just ${heart.margin} points short against ${l.opp}. One play, one catch, one lineup decision — that is all that separated victory from a loss that is going to sting all week.${heart.injuryText}`})}const lucky=[...wins].sort((a,b)=>a.score-b.score)[0];if(lucky)awards.push({label:'🍀 Lucky Bastard',text:`${lucky.name} escaped with a win despite scoring only ${lucky.score}, the lowest total among this week's winners. It was not pretty, but nobody gives the win back.`});const robbed=[...losses].sort((a,b)=>b.allPlayWins-a.allPlayWins||b.score-a.score)[0];if(robbed&&robbed.allPlayWins>=Math.ceil((teams.length-1)*.65))awards.push({label:'🤬 Robbed',text:`${robbed.name} dropped ${robbed.score} points and would have beaten ${robbed.allPlayWins} of the other ${teams.length-1} teams in the league. None of that matters now. They drew ${robbed.opp}, and the schedule showed absolutely no mercy.`});const collapse=losses.map(t=>({...t,edge:n(t.projection-(teams.find(o=>o.id!==t.id&&o.name===t.opp)?.projection||0))})).filter(t=>t.edge>=8).sort((a,b)=>b.edge-a.edge)[0];if(collapse)awards.push({label:'📉 Collapse',text:`${collapse.name} walked into the week as roughly an ${collapse.edge}-point projected favorite and somehow walked out with a loss to ${collapse.opp}. The projection said comfortable win. The scoreboard said disaster.`});const statement=wins.map(t=>({...t,oppAll:teams.find(o=>o.id!==t.id&&o.name===t.opp)?.allPlayWins||0})).sort((a,b)=>b.oppAll-a.oppAll)[0];if(statement&&statement.oppScore>=sorted[Math.floor(sorted.length/2)].score)awards.push({label:'👑 Statement Win',text:`${statement.name} did not beat a pushover. ${statement.opp} put up ${statement.oppScore} and still got sent home with a loss. That is the kind of win that makes the rest of the league take notice.`});const top=sorted[0],robbedText=robbed&&robbed.allPlayWins>=Math.ceil((teams.length-1)*.65)?` Meanwhile, ${robbed.name} got absolutely betrayed by the schedule despite scoring ${robbed.score}.`:'';return{awards:awards.slice(0,5),verdict:`Week ${displayWeek} belongs to ${top.name}. They dropped a league-best ${top.score} points${top.won?' and backed it up with a victory':' and somehow STILL walked away with a loss — fantasy football cruelty at its finest'}.${robbedText} The dust has settled, the excuses can begin, and the league moves on.`}};$: news=build();
</script>
<style>.news{width:95%;max-width:900px;margin:-12px auto 24px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.item,.verdict{padding:14px;border:1px solid var(--ccc);border-radius:14px;background:var(--fff);box-shadow:0 4px 14px rgba(0,0,0,.06)}.label{font-size:.7rem;font-weight:850;text-transform:uppercase;opacity:.62;margin-bottom:5px}.text{font-size:.86rem;line-height:1.45;font-weight:600}.verdict{margin-top:10px}.verdict .text{font-size:.92rem}@media(max-width:600px){.news{width:100%}.grid{grid-template-columns:1fr}.text{font-size:.8rem}}</style>
{#if news.awards.length||news.verdict}<section class="news"><div class="grid">{#each news.awards as a}<div class="item"><div class="label">{a.label}</div><div class="text">{a.text}</div></div>{/each}</div>{#if news.verdict}<div class="verdict"><div class="label">📰 Week {displayWeek} — GGL Newsroom Verdict</div><div class="text">{news.verdict}</div></div>{/if}</section>{/if}